const SLANG_ENTRIES = [{term: "rizz", era: "2020s", meaning: "Charisma, especially the ability to attract someone romantically."},{term: "no cap", era: "2020s", meaning: "No lie - genuinely telling the truth."},{term: "cap", era: "2020s", meaning: "A lie, or calling something out as false."},{term: "bet", era: "2010s-2020s", meaning: "Okay, sure, agreed - a casual confirmation."},{term: "bussin", era: "2020s", meaning: "Really good, especially describing food."},{term: "drip", era: "2010s-2020s", meaning: "Stylish, impressive clothing or overall look."},{term: "finna", era: "long-standing, mainstreamed 2020s", meaning: "\"Fixing to\" - about to do something."},{term: "ghost / ghosting", era: "2010s", meaning: "Suddenly cutting off all contact with someone without explanation."},{term: "glow up", era: "2010s", meaning: "A noticeable positive transformation in appearance or confidence over time."},{term: "GOAT", era: "2000s+", meaning: "\"Greatest Of All Time.\""},{term: "hits different", era: "2020s", meaning: "Feels notably better or more impactful in a specific moment or context."},{term: "IYKYK", era: "2010s-2020s", meaning: "\"If You Know You Know\" - a reference only insiders will get."},{term: "lowkey / highkey", era: "2010s", meaning: "Lowkey = secretly or to a small degree. Highkey = openly or to a large degree."},{term: "mid", era: "2020s", meaning: "Mediocre, unimpressive - neither good nor bad."},{term: "opp", era: "long-standing hip-hop/drill slang", meaning: "An opponent or enemy."},{term: "rent free", era: "2020s", meaning: "\"Living rent free in my head\" - something you can't stop thinking about."},{term: "simp", era: "2020s", meaning: "Someone who does excessive favors for a crush expecting nothing in return."},{term: "situationship", era: "2020s", meaning: "An undefined romantic relationship - more than friends, not officially dating."},{term: "slaps", era: "2010s-2020s", meaning: "Is really good, especially describing a song."},{term: "slay", era: "2010s-2020s", meaning: "Doing something exceptionally well, especially looking good."},{term: "stan", era: "2000s (from Eminem's 2000 song of the same name)", meaning: "An obsessive, devoted fan."},{term: "sus", era: "2020 (popularized by the game Among Us)", meaning: "Suspicious."},{term: "tea", era: "2010s", meaning: "Gossip, especially juicy personal information - \"spill the tea.\""},{term: "understood the assignment", era: "2020s", meaning: "Did exactly what was expected, and did it well."},{term: "valid", era: "2010s-2020s", meaning: "A reasonable or acceptable opinion or feeling."},{term: "based", era: "2010s-2020s", meaning: "Confidently being yourself or holding an opinion regardless of pushback."},{term: "cringe", era: "2010s+", meaning: "Embarrassing - causing secondhand embarrassment."},{term: "extra", era: "2010s", meaning: "Over-the-top or dramatic beyond what's necessary."},{term: "fam", era: "2010s", meaning: "A close friend, treated like family."},{term: "fire", era: "2010s+", meaning: "Excellent, impressive."},{term: "flex", era: "2010s+", meaning: "Showing off, especially something you're proud of."},{term: "fr fr", era: "2020s", meaning: "\"For real for real\" - emphasizing sincerity."},{term: "ick", era: "2020s", meaning: "A sudden feeling of being turned off by someone you were previously into."},{term: "main character energy", era: "2020s", meaning: "Carrying yourself like the protagonist of your own life."},{term: "NPC", era: "2020s", meaning: "\"Non-Player Character\" - acting robotic, unoriginal, or on autopilot."},{term: "periodt", era: "2020s", meaning: "Emphatic version of \"period\" - end of discussion."},{term: "ratio", era: "2020s", meaning: "When a reply gets more engagement than the original post, implying it was unpopular."},{term: "salty", era: "long-standing, still current", meaning: "Bitter or upset about something, often pettily."},{term: "savage", era: "2010s", meaning: "Brutally honest or fearless, sometimes harshly so."},{term: "shook", era: "2010s", meaning: "Shocked, visibly surprised."},{term: "snack", era: "2010s-2020s", meaning: "An attractive person."},{term: "touch grass", era: "2020s", meaning: "Go outside, get off the internet, gain some perspective."},{term: "vibe check", era: "2020s", meaning: "An informal assessment of the mood or energy of a person or situation."},{term: "yeet", era: "2010s-2020s", meaning: "To throw something with force; also an exclamation of excitement."},{term: "delulu", era: "2020s", meaning: "\"Delusional\" - used self-deprecatingly for an unrealistic hope."},{term: "it's giving ___", era: "2020s", meaning: "\"It has the vibe or energy of ___.\""},{term: "no thoughts head empty", era: "2020s", meaning: "A joking claim of not thinking about anything, often used ironically."},{term: "W / L", era: "2010s-2020s", meaning: "\"Win\" or \"loss\" - describing a good or bad outcome."},{term: "beige flag", era: "2020s", meaning: "A quirky, neutral trait in a partner - neither a good sign nor a bad one."},{term: "girl dinner", era: "2020s", meaning: "A playful term for a small, random assortment of snack foods eaten as a meal."}, ];function executeSlangSearch(){const query = document.getElementById("slang-search").value.trim().toLowerCase();const out = document.getElementById("slang-result");const matches = query ? SLANG_ENTRIES.filter((e) => e.term.toLowerCase().includes(query) || e.meaning.toLowerCase().includes(query)) : SLANG_ENTRIES;if (!matches.length){out.innerHTML = `<p style="color:var(--phosphor-dim-text); font-size:0.85rem;">// no entries match "${query}"</p>`;return;}out.innerHTML = `<div class="acronym-list">${matches
    .map(
      (e) => `<div class="acronym-entry">
        <span class="acronym-term" style="cursor:default;">${e.term}</span>
        <div>
          <span class="acronym-expansion">${e.meaning}</span>
          <span class="acronym-note">era: ${e.era}</span>
        </div>
      </div>`
    )
    .join("")}</div>`;}document.addEventListener("DOMContentLoaded", executeSlangSearch);